"""Pure invoice validation and event sorting utilities.

This module contains 30 independent, side-effect-free functions for validating
invoice records and sorting invoice-related events. All functions operate on
plain Python data (dicts, lists, tuples) and do not mutate their inputs.
"""

from __future__ import annotations

from typing import Any, Dict, Iterable, List, Optional, Sequence, Tuple


# ---------------------------------------------------------------------------
# Basic record helpers
# ---------------------------------------------------------------------------

def parse_record_id(record_id: str) -> int:
    """Parse a record identifier of the form 'R000123' into an integer.

    Raises ValueError if the identifier does not match the expected pattern.
    """
    if not isinstance(record_id, str):
        raise ValueError("record_id must be a string")
    if not record_id.startswith("R") or not record_id[1:].isdigit():
        raise ValueError(f"invalid record id: {record_id!r}")
    return int(record_id[1:])


def format_record_id(number: int) -> str:
    """Format an integer as a zero-padded record identifier 'R000123'."""
    if not isinstance(number, int) or number < 0:
        raise ValueError("number must be a non-negative integer")
    return f"R{number:06d}"


def record_to_dict(record: Dict[str, Any]) -> Dict[str, Any]:
    """Return a shallow copy of an invoice record dictionary."""
    if not isinstance(record, dict):
        raise TypeError("record must be a dict")
    return dict(record)


def record_field(record: Dict[str, Any], field: str, default: Any = None) -> Any:
    """Return a field from an invoice record, or a default if missing."""
    if not isinstance(record, dict):
        raise TypeError("record must be a dict")
    return record.get(field, default)


# ---------------------------------------------------------------------------
# Field-level validation
# ---------------------------------------------------------------------------

def validate_account(account: Any) -> bool:
    """Validate that an account identifier is a non-empty string."""
    return isinstance(account, str) and len(account) > 0


def validate_status(status: Any) -> bool:
    """Validate that a status is one of the known invoice statuses."""
    return isinstance(status, str) and status in {"paid", "pending", "void", "refunded"}


